contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient != address(0), "zero recipient");
        require(address(this).balance >= amount, "insufficient test balance");

        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        assert(
            reverted
                ? (cBalanceAfter == cBalanceBefore && recipientBalanceAfter == recipientBalanceBefore)
                : (cBalanceAfter == 0 && recipientBalanceAfter == recipientBalanceBefore + cBalanceBefore)
        );
    }

    receive() external payable {}
}

